INGRÉDIENTS ANALYTIQUES :
Protéine brute : 13%
Graisse brute : 3,5%
Fibre brute : 2%
Cendres brutes : 2,5%
Humidité : 18%
Paquet : 500g avec fermeture à ficelle pour garder le produit frais jusqu’au dernier régal.
Note logistique : nous n’expédions pas vers les Îles Canaries et Tenerife.',11.19,null,9.44,(select id from categories where universe='chien' and slug='friandises'),5,true,true,false,false,'[]'::jsonb,'{}'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'["images/img59.jpg","images/img60.jpg","images/img61.jpg"]'::jsonb,null,true,50) on conflict (legacy_id) do nothing;
insert into products(legacy_id,slug,name,subtitle,description,price,old_price,shipping,category_id,rating,is_best,is_new,is_promo,is_wellness,colors,color_images,sizes,size_guide,size_guide_head,pros,benefits,faq,images,video,in_stock,stock) values (28,'fontaine-pureflow-pour-chat-28','Fontaine PureFlow™ pour Chat','Fontaine à eau en acier inoxydable 304','Une hydratation pure, pour une vie plus saine
La fontaine PureFlow™ offre à votre chat une eau fraîche, filtrée et oxygénée en continu, qui l’encourage à boire davantage. Sa filtration multi-couches élimine impuretés, chlore et odeurs, tandis que sa pompe ultra-silencieuse (moins de 25 dB) fonctionne presque sans bruit. Réservoir en acier inoxydable 304 : hygiénique, durable et facile à nettoyer. Dimensions : 20,8 × 20,8 × 12 cm.',69.9,null,0,(select id from categories where universe='chat' and slug='hygiene'),5,true,true,false,true,'[]'::jsonb,'{}'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'["Eau filtrée, propre et saine","Ultra silencieuse (< 25 dB)","Circulation continue oxygénée","Acier inoxydable 304 hygiénique","Pompe à faible consommation"]'::jsonb,'["Encourage à boire davantage","Prévient la déshydratation","Soutient la santé rénale et urinaire","Eau fraîche en continu","Entretien simplifié"]'::jsonb,'[["La fontaine est-elle silencieuse ?","Oui, sa pompe fonctionne à moins de 25 dB, presque sans bruit."],["En quel matériau est-elle fabriquée ?","En acier inoxydable 304 : hygiénique, durable et résistant à la corrosion."],["L’eau est-elle filtrée ?","Oui, une filtration multi-couches élimine impuretés, chlore et odeurs."],["L’entretien est-il facile ?","Oui, le nettoyage est simple et le filtre se remplace facilement."]]'::jsonb,'["images/img62.jpg","images/img63.jpg","images/img64.jpg","images/img65.jpg","images/img66.jpg","images/img67.jpg","images/img68.jpg"]'::jsonb,null,true,50) on conflict (legacy_id) do nothing;
insert into products(legacy_id,slug,name,subtitle,description,price,old_price,shipping,category_id,rating,is_best,is_new,is_promo,is_wellness,colors,color_images,sizes,size_guide,size_guide_head,pros,benefits,faq,images,video,in_stock,stock) values (29,'brosse-vapeur-3-en-1-pour-chiens-29','Brosse Vapeur 3-en-1 pour Chiens','Brossage, vapeur et massage en un seul geste','Le toilettage version cocooning. Cette brosse vapeur diffuse une fine brume d’eau tiède qui humidifie le poil pour le démêler en douceur, capturer les poils morts et apaiser la peau. Ses picots souples en silicone massent et stimulent la circulation à chaque passage. Avec son réservoir intégré et sa recharge USB sans fil, elle rend le brossage facile, agréable et sans corvée. Idéale pour réduire la mue et garder un pelage doux et brillant.',24.63,null,0,(select id from categories where universe='chien' and slug='hygiene'),5,true,true,false,true,'["Blanc","Beige","Jaune","Vert"]'::jsonb,'{"Blanc":2,"Beige":0,"Jaune":5,"Vert":6}'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'["Vapeur fine qui démêle sans tirer","Picots souples en silicone, effet massant","Capture les poils morts et réduit la mue","Réservoir d’eau intégré","Rechargeable par USB, sans fil"]'::jsonb,'["Démêlage doux, sans douleur","Moins de poils dans la maison","Peau apaisée et mieux irriguée","Pelage doux et brillant","Un vrai moment de complicité"]'::jsonb,'[["La vapeur est-elle sans danger ?","Oui, c’est une fine brume d’eau tiède, douce pour la peau et le poil de votre compagnon."],["Comment se recharge-t-elle ?","Par câble USB. Une charge complète offre une longue autonomie."],["Convient-elle à tous les pelages ?","Oui, les picots en silicone s’adaptent aux poils courts comme longs."],["Faut-il remplir un réservoir ?","Oui, un petit réservoir intégré se remplit d’eau pour générer la vapeur."]]'::jsonb,'["images/img74.jpg","images/img75.jpg","images/img69.jpg","images/img70.jpg","images/img71.jpg","images/img72.jpg","images/img73.jpg"]'::jsonb,null,true,50) on conflict (legacy_id) do nothing;
insert into products(legacy_id,slug,name,subtitle,description,price,old_price,shipping,category_id,rating,is_best,is_new,is_promo,is_wellness,colors,color_images,sizes,size_guide,size_guide_head,pros,benefits,faq,images,video,in_stock,stock) values (30,'collier-cuir-grave-30','Collier Cuir Gravé','Cuir véritable, plaque en laiton gravée à votre nom','Un collier en cuir véritable au charme intemporel, personnalisé à votre image. La plaque en laiton se grave au nom de votre compagnon et à votre numéro — fini les médailles qui s’entrechoquent. Doublure rembourrée pour un confort optimal, boucle et anneaux en laiton massif, et coutures soignées. Réglable et décliné en plusieurs coloris, il allie élégance, solidité et sécurité au quotidien.',16.63,null,0,(select id from categories where universe='chien' and slug='colliers'),5,true,true,false,false,'["Gris","Marron","Vert","Rouge","Rose","Violet"]'::jsonb,'{"Gris":5,"Marron":4,"Vert":3,"Rouge":2,"Rose":6,"Violet":7}'::jsonb,'["XS","S","M","L","XL"]'::jsonb,'[["XS","32 cm","18–27 cm"],["S","37 cm","23–32 cm"],["M","42 cm","28–37 cm"],["L","50 cm","35–45 cm"],["XL","60 cm","42–55 cm"]]'::jsonb,'["Taille","Longueur totale","Tour de cou"]'::jsonb,'["Cuir véritable, finition soignée","Plaque en laiton gravée (nom + téléphone)","Doublure rembourrée, douce au toucher","Boucle et anneaux en laiton massif","Réglable, 5 tailles du XS au XL"]'::jsonb,'["Identification discrète et élégante","Aucun tintement de médaille","Confort sans irritation","Solide et durable","Un style unique pour votre compagnon"]'::jsonb,'[["Comment se fait la gravure ?","Vous indiquez le nom et le numéro souhaités lors de la commande, ils sont gravés sur la plaque en laiton."],["Quelle taille choisir ?","Mesurez le tour de cou de votre chien et laissez l’espace de deux doigts, puis reportez-vous au guide des tailles."],["Le cuir est-il résistant ?","Oui, c’est du cuir véritable robuste, conçu pour un usage quotidien."],["Convient-il aux petits chiens ?","Oui, la taille XS convient aux petits gabarits (tour de cou 18–27 cm)."]]'::jsonb,'["images/img78.jpg","images/img79.jpg","images/img80.jpg","images/img81.jpg","images/img82.jpg","images/img83.jpg","images/img84.jpg","images/img85.jpg"]'::jsonb,null,true,50) on conflict (legacy_id) do nothing;
insert into products(legacy_id,slug,name,subtitle,description,price,old_price,shipping,category_id,rating,is_best,is_new,is_promo,is_wellness,colors,color_images,sizes,size_guide,size_guide_head,pros,benefits,faq,images,video,in_stock,stock) values (31,'laisse-premium-reglable-pour-chat-31','Laisse Premium Réglable pour Chat','Harnais + laisse en maille respirante, réglable','Les balades en toute sérénité. Cet ensemble harnais + laisse en maille respirante épouse le corps de votre chat sans comprimer son cou : la pression est répartie sur le poitrail pour un confort optimal. Réglable et anti-fugue, il sécurise chaque sortie, tandis que sa maille aérée reste légère et agréable à porter. Laisse assortie incluse, dans une belle palette de coloris.',19.99,null,0,(select id from categories where universe='chat' and slug='colliers'),5,true,true,false,false,'["Rose vif","Noir","Vert","Rouge","Bleu ciel","Orange","Rose","Violet"]'::jsonb,'{"Rose vif":2,"Noir":3,"Vert":4,"Rouge":5,"Bleu ciel":6,"Orange":7,"Rose":8,"Violet":9}'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'["Maille respirante, légère et aérée","Réglable pour un ajustement parfait","Conception anti-fugue, ferme et sécurisée","Laisse assortie incluse","Écusson patte décoratif, plusieurs coloris"]'::jsonb,'["Des sorties en toute sécurité","Ne blesse pas le cou de votre chat","Confortable, même porté longtemps","Facile à mettre et à retirer","Un style assorti pour chaque chat"]'::jsonb,'[["Comment choisir la taille ?","Mesurez le tour de poitrail de votre chat ; les sangles réglables permettent un ajustement précis."],["Mon chat peut-il s’échapper ?","Bien ajusté, le harnais répartit la pression et reste sécurisé pour éviter les fugues."],["Convient-il aux chatons ?","Oui, grâce à son réglage, il s’adapte aussi bien aux chatons qu’aux chats adultes."],["Est-il lavable ?","Oui, la maille se nettoie facilement à la main et sèche rapidement."]]'::jsonb,'["images/img97.jpg","images/img98.jpg","images/img99.jpg","images/img100.jpg","images/img101.jpg","images/img102.jpg","images/img103.jpg","images/img104.jpg","images/img105.jpg","images/img106.jpg"]'::jsonb,null,true,50) on conflict (legacy_id) do nothing;
insert into products(legacy_id,slug,name,subtitle,description,price,old_price,shipping,category_id,rating,is_best,is_new,is_promo,is_wellness,colors,color_images,sizes,size_guide,size_guide_head,pros,benefits,faq,images,video,in_stock,stock) values (32,'hamac-fenetre-premium-pour-chat-32','Hamac Fenêtre Premium pour Chat','Hamac à ventouses pour fenêtre · 45 × 30 cm','Le poste d’observation préféré de votre chat. Ce hamac se fixe directement à la fenêtre grâce à de puissantes ventouses : votre chat profite du soleil et observe l’extérieur, confortablement installé en hauteur. Disponible en maille respirante pour l’été ou en peluche douce pour l’hiver, il supporte le poids de votre compagnon et s’installe en quelques secondes, sans outil ni trou. Une place douillette qui ne prend aucune place au sol.',35.34,null,0,(select id from categories where universe='chat' and slug='couchages'),5,true,true,false,false,'["Beige","Gris","Peluche grise"]'::jsonb,'{"Beige":1,"Gris":2,"Peluche grise":3}'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'["Ventouses robustes, fixation sûre","Maille respirante ou peluche douce","Vue sur l’extérieur + bain de soleil","Supporte le poids du chat","Installation sans outil, gain de place"]'::jsonb,'["Un poste d’observation en hauteur","Des siestes au soleil bien méritées","Libère de l’espace au sol","Apaise et occupe votre chat","Se déplace où vous voulez"]'::jsonb,'[["Les ventouses tiennent-elles bien ?","Oui, sur une vitre propre et lisse, les ventouses offrent une excellente adhérence. Nettoyez la surface avant la pose."],["Quel poids supporte-t-il ?","Il est conçu pour accueillir confortablement la plupart des chats ; répartissez bien les ventouses."],["La housse est-elle lavable ?","Oui, la housse se retire et se lave facilement pour rester toujours propre."],["Quelle est la taille ?","La surface mesure environ 45 × 30 cm, idéale pour s’allonger pleinement."]]'::jsonb,'["images/img112.jpg","images/img113.jpg","images/img114.jpg","images/img115.jpg","images/img116.jpg"]'::jsonb,'videos/hamac-fenetre.mp4',true,50) on conflict (legacy_id) do nothing;
